enum FilamentBackend {
  FILAMENT_BACKEND_DEFAULT(0),
  FILAMENT_BACKEND_OPENGL(1),
  FILAMENT_BACKEND_VULKAN(2),
  FILAMENT_BACKEND_METAL(3),
  FILAMENT_BACKEND_WEBGPU(4),
  FILAMENT_BACKEND_NOOP(5);

  final int value;
  const FilamentBackend(this.value);

  static FilamentBackend fromValue(int value) => switch (value) {
    0 => FILAMENT_BACKEND_DEFAULT,
    1 => FILAMENT_BACKEND_OPENGL,
    2 => FILAMENT_BACKEND_VULKAN,
    3 => FILAMENT_BACKEND_METAL,
    4 => FILAMENT_BACKEND_WEBGPU,
    5 => FILAMENT_BACKEND_NOOP,
    _ => throw ArgumentError('Unknown value for FilamentBackend: $value'),
  };
}

final class filament_engine_config_t extends ffi.Struct {
  filament_engine_config_t.$at(super.$address) : super.$at();

  int get command_buffer_size_mb => FlutterFilamentModule.heap.getUint32($address, Endian.little);
  set command_buffer_size_mb(int value) => FlutterFilamentModule.heap.setUint32($address, value, Endian.little);

  int get per_render_pass_arena_size_mb => FlutterFilamentModule.heap.getUint32($address + 4, Endian.little);
  set per_render_pass_arena_size_mb(int value) => FlutterFilamentModule.heap.setUint32($address + 4, value, Endian.little);

  int get min_command_buffer_size_mb => FlutterFilamentModule.heap.getUint32($address + 8, Endian.little);
  set min_command_buffer_size_mb(int value) => FlutterFilamentModule.heap.setUint32($address + 8, value, Endian.little);

  int get job_system_thread_count => FlutterFilamentModule.heap.getUint32($address + 12, Endian.little);
  set job_system_thread_count(int value) => FlutterFilamentModule.heap.setUint32($address + 12, value, Endian.little);

  int get preferred_shader_language => FlutterFilamentModule.heap.getInt32($address + 16, Endian.little);
  set preferred_shader_language(int value) => FlutterFilamentModule.heap.setInt32($address + 16, value, Endian.little);

  bool get force_gles2_context => FlutterFilamentModule.heap.getUint8($address + 20) != 0;
  set force_gles2_context(bool value) => FlutterFilamentModule.heap.setUint8($address + 20, value ? 1 : 0);

  int get gpu_context_priority => FlutterFilamentModule.heap.getInt32($address + 24, Endian.little);
  set gpu_context_priority(int value) => FlutterFilamentModule.heap.setInt32($address + 24, value, Endian.little);

  int get material_cache_capacity => FlutterFilamentModule.heap.getUint32($address + 28, Endian.little);
  set material_cache_capacity(int value) => FlutterFilamentModule.heap.setUint32($address + 28, value, Endian.little);

  int get stereoscopic_eye_count => FlutterFilamentModule.heap.getUint32($address + 32, Endian.little);
  set stereoscopic_eye_count(int value) => FlutterFilamentModule.heap.setUint32($address + 32, value, Endian.little);

  int get stereoscopic_type => FlutterFilamentModule.heap.getInt32($address + 36, Endian.little);
  set stereoscopic_type(int value) => FlutterFilamentModule.heap.setInt32($address + 36, value, Endian.little);
}

/// Live object counts of one engine: Filament's `Engine::get*Count()`,
/// the renderable / light / transform component counts, and the process-wide
/// entity count (entities are not per engine). Lets tests prove that a
/// viewport sharing an engine left nothing behind, and that a second viewport
/// on the same asset uploaded no new texture.
final class filament_engine_resource_counts_t extends ffi.Struct {
  filament_engine_resource_counts_t.$at(super.$address) : super.$at();

  int get textures => ffi.$readInt64($address);
  set textures(int value) => ffi.$writeInt64($address, value);

