/// Device-local memory of the GPU an engine renders on, as `VK_EXT_memory_budget`
/// reports it. `device_local_usage` is this *process's* usage of
/// the device-local heaps, `device_local_budget` what the driver says the
/// process can use, `device_local_size` the heaps' size; all bytes, summed
/// over every `VK_MEMORY_HEAP_DEVICE_LOCAL_BIT` heap.
final class filament_gpu_memory_t extends ffi.Struct {
  filament_gpu_memory_t.$at(super.$address) : super.$at();

  int get device_local_usage => ffi.$readInt64($address);
  set device_local_usage(int value) => ffi.$writeInt64($address, value);

  int get device_local_budget => ffi.$readInt64($address + 8);
  set device_local_budget(int value) => ffi.$writeInt64($address + 8, value);

  int get device_local_size => ffi.$readInt64($address + 16);
  set device_local_size(int value) => ffi.$writeInt64($address + 16, value);

  int get heap_count => FlutterFilamentModule.heap.getInt32($address + 24, Endian.little);
  set heap_count(int value) => FlutterFilamentModule.heap.setInt32($address + 24, value, Endian.little);
}

